<?php require 'includes/bootstrap.php';need_login();if(me()['role']==='admin')go('admin/index.php');$err=[];if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$sub=trim($_POST['subject']??'');$cat=$_POST['category']??'General';$msg=trim($_POST['message']??'');$cats=['Academic','Examination','Registration','Fees','Technical','General'];if(strlen($sub)<4||strlen($sub)>180)$err[]='Subject must be 4–180 characters.';if(!in_array($cat,$cats,true))$err[]='Choose a valid category.';if(strlen($msg)<10||strlen($msg)>5000)$err[]='Message must be 10–5000 characters.';if(!$err){$s=db()->prepare("INSERT INTO queries(user_id,subject,category,message) VALUES(?,?,?,?)");$s->execute([me()['id'],$sub,$cat,$msg]);flash('Query submitted successfully.');go('dashboard.php');}}$s=db()->prepare('SELECT * FROM queries WHERE user_id=? ORDER BY created_at DESC');$s->execute([me()['id']]);$qs=$s->fetchAll();$pageTitle='My dashboard';require 'includes/header.php';?><div><span class="eyebrow">STUDENT SPACE</span><h1>Hello, <?=e(me()['name'])?> 👋</h1><p>Submit questions and follow their progress.</p></div><div class="stats"><div class="stat">Total queries<strong><?=count($qs)?></strong></div><div class="stat">Pending<strong><?=count(array_filter($qs,fn($q)=>$q['status']==='pending'))?></strong></div><div class="stat">Resolved<strong><?=count(array_filter($qs,fn($q)=>$q['status']==='resolved'))?></strong></div></div><div class="form-card"><h2>Submit a new query</h2><?php foreach($err as $x):?><div class="alert error"><?=e($x)?></div><?php endforeach;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="field"><label>Subject</label><input name="subject" required minlength="4" maxlength="180"></div><div class="field"><label>Category</label><select name="category"><?php foreach(['Academic','Examination','Registration','Fees','Technical','General'] as $c):?><option><?=e($c)?></option><?php endforeach;?></select></div><div class="field"><label>Question</label><textarea name="message" required minlength="10" maxlength="5000"></textarea></div><button class="btn primary submit">Submit query</button></form></div><div class="panel"><h2>My queries</h2><?php if(!$qs):?><div class="empty">No queries submitted yet.</div><?php else:?><table><tr><th>Subject / response</th><th>Category</th><th>Status</th><th>Submitted</th></tr><?php foreach($qs as $q):?><tr><td><b><?=e($q['subject'])?></b><p><?=nl2br(e($q['message']))?></p><?php if($q['admin_response']):?><div class="answer"><b>Admin response:</b><br><?=nl2br(e($q['admin_response']))?></div><?php endif;?></td><td><?=e($q['category'])?></td><td><span class="status status-<?=e($q['status'])?>"><?=e(ucwords(str_replace('_',' ',$q['status'])))?></span></td><td><?=e($q['created_at'])?></td></tr><?php endforeach;?></table><?php endif;?></div><?php require 'includes/footer.php';?>